class TextTools {

  // a) zählt die Großbuchstaben A-Z
  public int zaehleGrossbuchstaben(String text) {
    int anzahl = 0;
    for (int i = 0; i < text.length(); i++) {
      char c = text.charAt(i);
      if (c >= 'A' && c <= 'Z') {
        anzahl++;
      }
    }
    return anzahl;
  }

  // b) größter Wert eines nicht leeren int-Arrays
  public int maximum(int[] zahlen) {
    int max = zahlen[0];
    for (int i = 1; i < zahlen.length; i++) {
      if (zahlen[i] > max) {
        max = zahlen[i];
      }
    }
    return max;
  }

  public static void main(String[] s) {
    TextTools t = new TextTools();
    System.out.println(t.zaehleGrossbuchstaben("Hallo Welt"));
    System.out.println(t.maximum(new int[]{3, 8, 1, 7}));
  }
}

